-- ERP-0071 stages 2-4 (2026-11-19): website content as structured entries per
-- page_type (commerce.web_pages, validated by the shared content-type registry)
-- and uploaded website images (commerce.web_assets). Company-wide (ADR-0012,
-- ADR-0025); soft delete; generated by drizzle-kit and inspected.
CREATE TABLE "commerce"."web_assets" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"object_key" text NOT NULL,
	"file_name" text NOT NULL,
	"content_type" varchar(64) DEFAULT 'image/webp' NOT NULL,
	"byte_size" integer DEFAULT 0 NOT NULL,
	"alt_text" text,
	"uploaded_by_user_id" text,
	"created_at" bigint NOT NULL,
	"updated_at" bigint NOT NULL,
	"deleted_at" bigint,
	CONSTRAINT "web_assets_byte_size_check" CHECK ("byte_size" >= 0)
);
--> statement-breakpoint
CREATE TABLE "commerce"."web_pages" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7(),
	"page_type" text NOT NULL,
	"slug" varchar(128) NOT NULL,
	"title" text NOT NULL,
	"status" text DEFAULT 'draft' NOT NULL,
	"published_at" bigint,
	"position" integer DEFAULT 0 NOT NULL,
	"content" jsonb DEFAULT '{}' NOT NULL,
	"seo_title" text,
	"seo_description" text,
	"version" integer DEFAULT 1 NOT NULL,
	"updated_by_user_id" text,
	"created_at" bigint NOT NULL,
	"updated_at" bigint NOT NULL,
	"deleted_at" bigint,
	CONSTRAINT "web_pages_page_type_check" CHECK ("page_type" IN ('home', 'about', 'careers', 'warranty', 'installation', 'solution', 'project', 'testimonial', 'help_topic', 'help_article', 'faq_group', 'help_document', 'help_video', 'training_course', 'news', 'career_role', 'legal')),
	CONSTRAINT "web_pages_status_check" CHECK ("status" IN ('draft', 'published', 'archived')),
	CONSTRAINT "web_pages_version_check" CHECK ("version" > 0)
);
--> statement-breakpoint
CREATE UNIQUE INDEX "web_assets_object_key_uq" ON "commerce"."web_assets" ("object_key");--> statement-breakpoint
CREATE UNIQUE INDEX "web_pages_type_slug_uq" ON "commerce"."web_pages" ("page_type","slug") WHERE deleted_at IS NULL;--> statement-breakpoint
CREATE INDEX "web_pages_type_status_position_idx" ON "commerce"."web_pages" ("page_type","status","position");